from pathlib import Path
import re
exec(Path('scripts/version9.py').read_text(encoding='utf-8'))
p=Path('app/src/main/java/se/linje11/gps/MainActivity.java')
s=p.read_text(encoding='utf-8')

# TTS for turn guidance.
s=s.replace('import android.webkit.*;', 'import android.webkit.*;\nimport android.speech.tts.TextToSpeech;')
s=s.replace('import java.nio.charset.StandardCharsets;', 'import java.nio.charset.StandardCharsets;\nimport java.util.Locale;')
s=s.replace('private LinearLayout routeList; private Spinner daySpinner; private String selectedDay="Måndag"; private JSONObject pendingRoute;', 'private LinearLayout routeList; private Spinner daySpinner; private String selectedDay="Måndag"; private JSONObject pendingRoute; private TextToSpeech tts;')
s=s.replace('@Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);showDayChooser();}', '@Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);tts=new TextToSpeech(this,x->{if(x==TextToSpeech.SUCCESS)tts.setLanguage(new Locale("sv","SE"));});showDayChooser();}')

# Extend existing Android bridge with speech support.
old='web.addJavascriptInterface(new Object(){@JavascriptInterface public void chooseRoute(){runOnUiThread(()->showRouteChooser());}},"Android");'
new='web.addJavascriptInterface(new Object(){@JavascriptInterface public void chooseRoute(){runOnUiThread(()->showRouteChooser());}@JavascriptInterface public void speakMessage(String m){runOnUiThread(()->{if(tts!=null)tts.speak(m,TextToSpeech.QUEUE_FLUSH,null,"nav");});}},"Android");'
s=s.replace(old,new)

# Replace map HTML with Lenninge-style navigation: first guide to START, then automatic A/B/C navigation.
start=s.index(' private String mapHtml(JSONObject route)throws Exception{')
end=s.index(' @Override public void onBackPressed()', start)
method=r''' private String mapHtml(JSONObject route)throws Exception{
  JSONArray points=route.optJSONArray("points"),stops=route.optJSONArray("stops");if(points==null||points.length()==0)throw new Exception("no points");
  StringBuilder p=new StringBuilder("[");for(int i=0;i<points.length();i++){JSONObject o=points.getJSONObject(i);if(i>0)p.append(',');p.append('[').append(o.getDouble("lat")).append(',').append(o.getDouble("lon")).append(']');}p.append(']');
  StringBuilder m=new StringBuilder("[");if(stops!=null)for(int i=0;i<stops.length();i++){JSONObject o=stops.getJSONObject(i);if(i>0)m.append(',');String name=o.optString("name","").replace("\\","\\\\").replace("'","\\'");String label=o.optString("label",String.valueOf((char)('A'+i)));m.append("{lat:").append(o.getDouble("lat")).append(",lon:").append(o.getDouble("lon")).append(",label:'").append(label).append("',name:'").append(name).append("'}");}m.append(']');
  JSONObject st=route.optJSONObject("start"),en=route.optJSONObject("end");
  String startJs=st==null?"null":"{lat:"+st.getDouble("lat")+",lon:"+st.getDouble("lon")+",label:'START'}";
  String endJs=en==null?"null":"{lat:"+en.getDouble("lat")+",lon:"+en.getDouble("lon")+",label:'SLUT'}";
  return "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no'><link rel='stylesheet' href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'><style>html,body,#map{height:100%;margin:0}body{font-family:sans-serif}#top{position:absolute;z-index:9999;top:10px;left:10px;right:10px;background:#fff;padding:9px 12px;border-radius:14px;box-shadow:0 3px 14px #0006;border-left:7px solid #d32f2f}#title{font-size:19px;font-weight:900}#label{font-size:12px;font-weight:900;color:#d32f2f;margin-top:2px}#status{font-size:18px;font-weight:900;line-height:1.16;display:block;margin-top:2px}#turn{font-size:21px;font-weight:900;display:block;margin-top:5px;color:#111}#eta{font-size:13px;color:#222;display:block;margin-top:2px}#routeStatus{font-size:13px;color:#1769aa;display:block;margin-top:4px}#gpsStatus{font-size:13px;color:#555;display:block;margin-top:2px}.pin{background:#fff;border:4px solid #1769aa;border-radius:50%;width:42px;height:42px;line-height:34px;text-align:center;font-weight:bold;font-size:20px;box-sizing:border-box}.next{border-color:#d32f2f;box-shadow:0 0 0 5px #d32f2f44}.gpsDot{width:24px;height:24px;background:#1976d2;border:4px solid white;border-radius:50%;box-shadow:0 0 0 3px #1976d266}.special{color:#fff;border:4px solid #fff;border-radius:18px;padding:5px 9px;font:bold 12px sans-serif;box-shadow:0 2px 6px #555}.controls{position:absolute;z-index:9999;left:10px;right:10px;bottom:18px;display:flex;gap:8px;pointer-events:none}.controls button{pointer-events:auto;flex:1;background:white;border:0;border-radius:13px;padding:12px 8px;font-size:15px;font-weight:bold;box-shadow:0 2px 8px #0004;color:#17365d}</style></head><body><div id='top'><div id='title'>Rutt GPS • Körnavigation</div><div id='label'>STARTAR NAVIGATION</div><span id='status'>Söker GPS…</span><span id='turn'>🧭 Beräknar vägen…</span><span id='eta'></span><span id='routeStatus'>Arbetsrutten visas ✓</span><span id='gpsStatus'>🔵 Söker GPS…</span></div><div id='map'></div><div class='controls'><button onclick='showRoute()'>🗺 Visa hela rutten</button><button onclick='myGps()'>🔵 Min GPS</button><button onclick='Android.chooseRoute()'>🔄 Byt rutt / dag</button></div><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script><script>var pts="+p+",stops="+m+",start="+startJs+",end="+endJs+";var map=L.map('map',{zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);var line=L.polyline(pts,{color:'#1976d2',weight:7,opacity:.95}).addTo(map);map.fitBounds(line.getBounds(),{padding:[35,35]});var markers=[];function mkIcon(t,n){return L.divIcon({className:'',html:'<div class=\"pin '+(n?'next':'')+'\">'+t+'</div>',iconSize:[46,46],iconAnchor:[23,23]});}stops.forEach(function(s,i){markers[i]=L.marker([s.lat,s.lon],{icon:mkIcon(s.label,false)}).addTo(map);if(s.name)markers[i].bindTooltip(s.name,{permanent:true,direction:'right',offset:[18,0],className:'stopName'});});if(start)L.marker([start.lat,start.lon],{icon:L.divIcon({className:'',html:'<div class=\"special\" style=\"background:#2e7d32\">START</div>',iconSize:[64,32],iconAnchor:[32,16]})}).addTo(map);if(end)L.marker([end.lat,end.lon],{icon:L.divIcon({className:'',html:'<div class=\"special\" style=\"background:#c62828\">SLUT</div>',iconSize:[58,32],iconAnchor:[29,16]})}).addTo(map);var gps=null,acc=null,lastGps=null,follow=true,phase=start?'start':'route',idx=0,lastRoad=0,roadKm=null,roadSec=null,nextTurn=null,nearHits=0,lastSpoken='';function showRoute(){follow=false;map.fitBounds(line.getBounds(),{paddingTopLeft:[30,300],paddingBottomRight:[30,90]});}function myGps(){follow=true;if(lastGps)map.setView(lastGps,16,{animate:true});}function target(){if(phase==='start')return start;if(idx<stops.length)return stops[idx];return end;}function km(a,b){var R=6371,dLat=(b[0]-a[0])*Math.PI/180,dLon=(b[1]-a[1])*Math.PI/180,la=a[0]*Math.PI/180,lb=b[0]*Math.PI/180,x=Math.sin(dLat/2)**2+Math.cos(la)*Math.cos(lb)*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}async function road(a,b){var u='https://router.project-osrm.org/route/v1/driving/'+a[1]+','+a[0]+';'+b.lon+','+b.lat+'?overview=false&steps=true';var r=await fetch(u),d=await r.json();if(!d.routes||!d.routes.length)throw Error();return d.routes[0];}function turnText(rr){try{var ss=rr.legs[0].steps||[];for(var i=0;i<ss.length;i++){var q=ss[i],type=(q.maneuver.type||'').toLowerCase(),mod=(q.maneuver.modifier||'').toLowerCase();if(type==='depart'||type==='arrive'||q.distance<5)continue;var icon='⬆️',txt='Fortsätt rakt fram';if(type.indexOf('roundabout')>=0){icon='🔄';txt='Kör in i rondellen';if(q.maneuver.exit)txt+=' och ta avfart '+q.maneuver.exit;}else if(mod.indexOf('left')>=0){icon=mod.indexOf('slight')>=0?'↖️':'⬅️';txt=mod.indexOf('slight')>=0?'Håll svagt vänster':'Sväng vänster';}else if(mod.indexOf('right')>=0){icon=mod.indexOf('slight')>=0?'↗️':'➡️';txt=mod.indexOf('slight')>=0?'Håll svagt höger':'Sväng höger';}if(q.name)txt+=' mot '+q.name;return{icon:icon,text:txt,d:q.distance,key:type+'|'+mod+'|'+q.name};}}catch(e){}return null;}function fmt(t){if(!t)return'⬆️ Följ vägen';var d=t.d<1000?Math.round(t.d)+' m':(t.d/1000).toFixed(1)+' km';return t.icon+' '+t.text+' om '+d;}function eta(sec){if(sec==null)return'';var m=Math.max(1,Math.round(sec/60));return m<60?'Beräknad körtid: '+m+' min':'Beräknad körtid: '+Math.floor(m/60)+' h '+(m%60)+' min';}function refreshMarkers(){markers.forEach((m,i)=>m.setIcon(mkIcon(stops[i].label,phase==='route'&&i===idx)));}function info(){var t=target(),lab=document.getElementById('label'),st=document.getElementById('status');if(!t){lab.textContent='RUTTEN KLAR ✓';st.textContent='Alla stopp är klara';document.getElementById('turn').textContent='✅ Rutten är färdig';return;}if(phase==='start'){lab.textContent='KÖR TILL STARTPUNKT';st.textContent='Nästa: START';}else{lab.textContent='NÄSTA STOPP • '+(idx+1)+'/'+stops.length;st.textContent='Nästa: '+t.label+(t.name?' • '+t.name:'');}if(roadKm!=null)st.textContent+=' • 🚗 '+(roadKm<1?Math.round(roadKm*1000)+' m':roadKm.toFixed(1)+' km')+' bilväg';document.getElementById('turn').textContent=fmt(nextTurn);document.getElementById('eta').textContent=eta(roadSec);refreshMarkers();}async function updateRoad(force){var t=target();if(!lastGps||!t||(!force&&Date.now()-lastRoad<6500))return;lastRoad=Date.now();try{var rr=await road(lastGps,t);roadKm=rr.distance/1000;roadSec=rr.duration;nextTurn=turnText(rr);if(nextTurn&&nextTurn.d<=650&&nextTurn.key!==lastSpoken){lastSpoken=nextTurn.key;try{Android.speakMessage(nextTurn.text+' om '+Math.max(50,Math.round(nextTurn.d/50)*50)+' meter');}catch(e){}}}catch(e){roadKm=null;roadSec=null;nextTurn=null;}info();}function arrived(){var t=target();if(!lastGps||!t)return;var d=km(lastGps,[t.lat,t.lon])*1000;if(d<45)nearHits++;else nearHits=0;if(nearHits<2)return;nearHits=0;if(phase==='start'){phase='route';idx=0;lastSpoken='';try{Android.speakMessage('Startpunkten är nådd. Ruttnavigeringen börjar.');}catch(e){}}else if(phase==='route'){if(idx<stops.length-1){idx++;try{Android.speakMessage('Nästa stopp '+stops[idx].label); }catch(e){}}else{phase='end';if(end)try{Android.speakMessage('Alla stopp klara. Kör till slutpunkten.');}catch(e){}}}else if(phase==='end'){phase='done';try{Android.speakMessage('Rutten är klar.');}catch(e){}}roadKm=null;roadSec=null;nextTurn=null;updateRoad(true);info();}navigator.geolocation.watchPosition(function(pos){lastGps=[pos.coords.latitude,pos.coords.longitude];if(!gps)gps=L.marker(lastGps,{icon:L.divIcon({className:'',html:'<div class=\"gpsDot\"></div>',iconSize:[32,32],iconAnchor:[16,16]})}).addTo(map);else gps.setLatLng(lastGps);if(acc)map.removeLayer(acc);acc=L.circle(lastGps,{radius:pos.coords.accuracy,color:'#1687ff',weight:1,fillOpacity:.08}).addTo(map);document.getElementById('gpsStatus').textContent='🔵 GPS hittad • ±'+Math.round(pos.coords.accuracy)+' m';if(follow)map.setView(lastGps,16,{animate:true});arrived();updateRoad(false);},function(){document.getElementById('gpsStatus').textContent='GPS kunde inte hämtas';},{enableHighAccuracy:true,maximumAge:1000,timeout:10000});info();</script></body></html>";
 }
'''
s=s[:start]+method+s[end:]

# Version bump/title.
s=s.replace('VERSION 9 • RUTTBIBLIOTEK','VERSION 10 • RUTTBIBLIOTEK').replace('VERSION 9 • "+selectedDay.toUpperCase()','VERSION 10 • "+selectedDay.toUpperCase()')
# Ensure TTS is shut down.
insert=' @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}\n'
pos=s.rfind('\n}')
s=s[:pos]+insert+s[pos:]
p.write_text(s,encoding='utf-8')
b=Path('app/build.gradle');t=b.read_text(encoding='utf-8').replace('versionCode 9','versionCode 10').replace('versionName "9.0"','versionName "10.0"');b.write_text(t,encoding='utf-8')
